// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(uint8 roleIdx, address actor) public {
        vm.assume(actor != address(0));
        bytes32[3] memory roles = [
            c.TIMELOCK_ADMIN_ROLE(),
            c.PROPOSER_ROLE(),
            c.EXECUTOR_ROLE()
        ];
        bytes32 role = roles[bound(uint256(roleIdx), 0, 2)];

        // grant the role to actor via the role's admin (deployer holds TIMELOCK_ADMIN_ROLE)
        c.grantRole(role, actor);
        assertTrue(c.hasRole(role, actor));

        // actor renounces their own role
        vm.prank(actor);
        c.renounceRole(role, actor);

        // RULE: after renouncing a role, the account no longer holds it.
        assertTrue(!c.hasRole(role, actor));
    }
}
